// ─────────────────────────────────────────────────────────────────────────────
// Pri Learning · what a build of one edition carries as its brand (plan E4)
//
// The build side of the edition brand. client/vite.config.js calls these with
// the edition the build resolved from PRI_EDITION (featureStates().edition), so
// index.html, the web manifest, the favicon, the splash and the app icons of a
// build are that edition's and only that edition's. The student app reads the
// same table through client/src/brand/edition.js.
//
// Source files: client/brand/<edition>/ (generated by tools/brand/build-assets.mjs
// and tools/brand/rasterise-icons.mjs). Decision record: docs/brand/editions-decision.md.
// ─────────────────────────────────────────────────────────────────────────────
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { join } from 'node:path';
import { EDITIONS, editionOf } from '../edition.config.mjs';

const HERE = fileURLToPath(new URL('.', import.meta.url));

/** The files a build copies to its root, from client/brand/<edition>/. */
export const WEB_FILES = Object.freeze([
  'favicon.svg',
  'mask-icon.svg',
  'splash.svg',
  'icons/icon-180.png',
  'icons/icon-192.png',
  'icons/icon-512.png',
  'icons/icon-maskable-192.png'
]);

/** Browser chrome and install-splash colour: the light desk (client/src/lib/theme.js THEME_CHROME.light). */
export const CHROME_LIGHT = '#f2f0ea';

export const brandFile = (id, rel) => join(HERE, editionOf(id).id, rel);

/** The web app manifest of an edition's build, as an object. */
export function webManifest(id) {
  const e = editionOf(id);
  return {
    name: e.brand,
    short_name: e.brand,
    description: e.identity.description,
    lang: e.locale,
    categories: ['education'],
    start_url: '/',
    scope: '/',
    display: 'standalone',
    orientation: 'any',
    background_color: CHROME_LIGHT,
    theme_color: CHROME_LIGHT,
    icons: [
      { src: '/icons/icon-192.png', sizes: '192x192', type: 'image/png' },
      { src: '/icons/icon-512.png', sizes: '512x512', type: 'image/png' },
      { src: '/icons/icon-maskable-192.png', sizes: '192x192', type: 'image/png', purpose: 'maskable' }
    ]
  };
}

/**
 * The accent tokens, as the one <style> block index.html carries. Only this
 * edition's colours are in its build. client/test/brand-usage-check.mjs keeps
 * --edition-accent to the brand mark.
 */
export function editionTokensCss(id) {
  const { accent, onAccent } = editionOf(id).identity;
  return `html{--edition-accent:${accent.light};--edition-on-accent:${onAccent.light}}`
    + `html[data-theme="dark"]{--edition-accent:${accent.dark};--edition-on-accent:${onAccent.dark}}`;
}

const escapeHtml = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

/**
 * Fill client/index.html's %PRI_…% placeholders for an edition. Throws if one
 * is left, so a new placeholder can never reach a shipped page unfilled.
 * The Hindi boot-guard line exists only for an edition that offers Hindi.
 */
export function brandIndexHtml(html, id) {
  const e = editionOf(id);
  const hi = e.languages.includes('hi') && e.identity.brandHi ? escapeHtml(e.identity.brandHi) : null;
  const values = {
    PRI_EDITION: e.id,
    PRI_BRAND: escapeHtml(e.brand),
    PRI_BRAND_HI: hi || escapeHtml(e.brand),
    PRI_DESCRIPTION: escapeHtml(e.identity.description),
    PRI_ACCENT: e.identity.accent.light,
    PRI_EDITION_TOKENS: editionTokensCss(id),
    PRI_BOOT_SLOW_HI: hi
      ? `<p lang="hi">${hi} अभी लोड हो रहा है। इसमें जितना लगना चाहिए उससे ज़्यादा समय लग रहा है। आप इंतज़ार कर सकते हैं, या दोबारा लोड कर सकते हैं।</p>`
      : '',
    PRI_BOOT_RELOAD: hi
      ? `Reload ${escapeHtml(e.brand)} · ${hi} फिर से लोड करें`
      : `Reload ${escapeHtml(e.brand)}`
  };
  const out = html.replace(/%(PRI_[A-Z_]+)%/g, (whole, name) => (Object.hasOwn(values, name) ? values[name] : whole));
  const left = out.match(/%PRI_[A-Z_]+%/);
  if (left) throw new Error(`client/index.html has an unfilled brand placeholder ${left[0]}`);
  return out;
}

/** client/index.html as the given edition's build serves it. */
export function builtIndexHtml(id) {
  return brandIndexHtml(readFileSync(join(HERE, '../index.html'), 'utf8'), id);
}

export const BRAND_EDITION_IDS = Object.freeze(Object.keys(EDITIONS));
